def get_counter_name_version(name, major="8",minor="16.0"):
    full = False
    old_name = name
    #print ("CNT:%s %s %s"%(name, full, minor))
    try:
        if "," in name and name.split(",")[0] in VERSION_COMPATIBILITY["counters_list"]:
            name = name.split(",")[0]
            full = True
            if minor in VERSION_COMPATIBILITY["counters_list"][name]:
                name = VERSION_COMPATIBILITY["counters_list"][name][minor]
            else:
                name = VERSION_COMPATIBILITY["counters_list"][name]["default"]
            if not full and "," in name:
                name = name.split(",")[0]
        elif "->"not in name:
            if minor in VERSION_COMPATIBILITY["counters_list"][name]:
                name = VERSION_COMPATIBILITY["counters_list"][name][minor]
            else:
                name = VERSION_COMPATIBILITY["counters_list"][name]["default"]
            name = name.split(",")[0]
        elif "->"in name:
            #print ("Checking AM counetr")
            if minor in VERSION_COMPATIBILITY["am_counters"][name]:
                #print (minor)
                name = VERSION_COMPATIBILITY["am_counters"][name][minor]
            else:
                name = VERSION_COMPATIBILITY["am_counters"][name]["default"]
    except Exception as e:
        #try/except WOW
        #print ("restore old name for %s"%e) 
        name= old_name
        pass
    #print ("CNU:%s %s %s"%(name, full, minor))
    return name

